// PandaDoc on an API key: every operation of PandaDoc's public API. actions.json is generated by
// `bun scripts/openapi-actions.ts pandadoc`; documents, recipients and templates start automations by webhook (triggers.ts).
import type { OwnApp } from "../index";
import { type Api, call, type Send, specActions } from "../openapi";
import { AppFile } from "../../types";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const api: Api = {
  name: "PandaDoc",
  base: "https://api.pandadoc.com",
  tokenHelp: "app.pandadoc.com/a/#/settings/integrations/api",
  auth: (key) => ({ Authorization: `API-Key ${key}` }),
};

const file = new URL("./actions.json", import.meta.url);
const actions = await specActions(file, api);
for (const { name, send } of (await Bun.file(file).json()).actions as { name: string; send: Send }[]) {
  const action = actions[name]!;
  const run = action.run;
  // uploads are told apart by a bare flag in the path (/documents?upload); it goes in the query with the rest, as upload=
  const [path, flag] = send.path.split("?");
  action.run = async (input: Record<string, unknown>, key) => {
    const out = flag ? await call(api, key, { ...send, path: path!, query: [...send.query, flag] }, { ...input, [flag]: "" }) : await run(input, key);
    // a download comes back named after the last bit of its path ("download"): give it a name with its type
    if (!(out instanceof AppFile) || out.name.includes(".")) return out;
    const ext = out.mimetype === "application/pdf" ? "pdf" : out.mimetype.includes("wordprocessingml") ? "docx" : (out.mimetype.split("/")[1] ?? "bin");
    return new AppFile(`${String(input.attachment_id ?? input.id ?? input.document_id ?? "pandadoc")}.${ext}`, out.mimetype, out.bytes);
  };
}

export const pandadoc: OwnApp = {
  app: "pandadoc",
  name: "PandaDoc",
  logo: "/logos/pandadoc.svg",
  keyField: {
    label: "API key",
    help: "In PandaDoc open Settings → Integrations → API (app.pandadoc.com/a/#/settings/integrations/api), create a key and copy it. A live (production) key needs PandaDoc's Enterprise or API plan; a free sandbox key works for trying Emplio out, but sandbox documents are watermarked and can only be sent to people in your own workspace.",
    placeholder: "3039ba033eb1410caa0a2227158d63c9d6502cd8",
  },
  async check(key) {
    const me = (await call(api, key, { method: "GET", path: "/public/v1/members/current", query: [], headers: [] }, {})) as { email?: string; workspace_name?: string };
    return [me.email, me.workspace_name && `(${me.workspace_name})`].filter(Boolean).join(" ") || undefined;
  },
  push: {
    events,
    triggers,
    start: (key, connection, event) => watch(api, key, connection, event),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery) => receive(delivery),
    wanted,
  },
  actions: {
    ...actions,
    // Composio has two names for the same search
    search_product_catalog_items: actions.search_catalog_items!,
  },
};
